# P46 — the Synthea limitations (US Core profiles; Chen et al.'s validity bounds) stated once, in §3.5;
# §5.8 and §6.7 point there (PRES-4, M4d).
EDITS = [{'id': 'P46-01', 'file': 'Chapter5_Demonstration_v1.md', 'old': "One limitation of the generated cohort is carried forward. Synthea's default export conforms to US Core profiles with United States demographics and care patterns, not to the Norwegian basisprofiler (HL7 Norway, 2025). The FHIR version matches Norway's, the resource structure is genuine, and the invariance result above establishes that the mismatch cannot affect any figure in this chapter. But no claim of Norwegian clinical representativeness is made for the records. The thesis's Norwegian grounding rests on the infrastructure analysis of Chapter 4, Section 4.11 rather than on the synthetic population.", 'new': 'The generated records carry US Core profiles, not the Norwegian basisprofiler; Chapter 3, Section 3.5 states why that cannot affect any figure here, and the invariance above confirms it.', 'why': 'PRES-4: said once in §3.5'}, {'id': 'P46-02', 'file': 'Chapter6_Discussion_v1.md', 'old': 'Chapter 3 specified a two-layer sandbox: a feasibility checker carrying the load-bearing claim, and a realism layer feeding it Synthea-generated FHIR records. Both were built and both were run, and the result of running the second is more informative than its mere existence.\n\n', 'new': '', 'why': 'PRES-1/PRES-4'}, {'id': 'P46-03', 'file': 'Chapter6_Discussion_v1.md', 'old': "Two limitations of the generated cohort are carried forward rather than resolved.\n\nSynthea's default export conforms to the US Core implementation guide, with United States demographic, geographic, and care-pattern parameters. The FHIR version matches the version the Norwegian basisprofiler constrain, and the resource structure is genuine, but the profiles are not Norwegian and no claim of Norwegian clinical representativeness is made for the records. The invariance result establishes that this cannot affect any figure, and the thesis's Norwegian grounding rests on the infrastructure analysis of Chapter 4, Section 4.11 rather than on the synthetic population. Had the thesis made epidemiological or clinical claims, this limitation would be disqualifying; because its claims concern the behaviour of audit records under constraint, it is not.\n\nSynthea's validity has itself been assessed. Chen and colleagues found the generator reliable in modelling demographics and the probability of services being offered, and limited in modelling heterogeneous outcomes following intervention and regional variation in care quality (Chen, Chun, Patel, Chiang, & James, 2019). The same reasoning applies: the limitations are in dimensions this thesis does not use.\n\n", 'new': 'The two limitations of the generated cohort, US Core rather than Norwegian profiles and the validity bounds found by Chen, Chun, Patel, Chiang and James (2019), are stated in Chapter 3, Section 3.5; both lie in dimensions the thesis does not use, because its claims concern the behaviour of audit records under constraint, not clinical content.\n\n', 'why': 'PRES-4: said once in §3.5'}]
LOST_OK = ["citation HL7 Norway, 2025", "number 4", "number 2025", "number 4.11", "citation Chen, Chun, Patel, Chiang, & James, 2019", "hedge cannot"]   # all in §3.5, which now carries the statement once; Chen cited narratively
